%[text] # BEV Controller - Simulation Case
%[text] ## Simple
model_name = "HarnessModel_BEVController";
load_system(model_name) 

BEVController_Basic_params

set_param(model_name + "/BEV Speed Tracking Controller", ReferencedSubsystem = "BEVController_Basic_refsub");

set_param(model_name + "/Inputs", ReferencedSubsystem = "Inputs_BEVController_Random_refsub");
%[text] 
sim_in = Simulink.SimulationInput(model_name);
sim_in = setModelParameter(sim_in, StopTime = "2000");

sim_out = sim(sim_in);

simResultTimetable = extractTimetable(sim_out.logsout);
%[text] 
fig = figure; %[output:51f4088c]
hold on %[output:51f4088c]
grid on %[output:51f4088c]
axis padded %[output:51f4088c]
fig.Position(3:4) = [700 300];  % width height %[output:51f4088c]

plot(simResultTimetable, "Time", "Vehicle speed input kph", LineWidth=2) %[output:51f4088c]
title("Input to controller: Vehicle target speed") %[output:51f4088c]
ylabel("km/h") %[output:51f4088c]
fig = figure; %[output:9d7a1f35]
hold on %[output:9d7a1f35]
grid on %[output:9d7a1f35]
axis padded %[output:9d7a1f35]
fig.Position(3:4) = [700 300];  % width height %[output:9d7a1f35]

plot(simResultTimetable, "Time", "Motor torque command", LineWidth=2) %[output:9d7a1f35]
title("Output from controller: Motor torque command") %[output:9d7a1f35]
ylabel("N*m") %[output:9d7a1f35]
